module Fastlane
  module Actions
    module SharedValues
      DSYM_PATHS = :DSYM_PATHS
      DSYM_LATEST_UPLOADED_DATE = :DSYM_LATEST_UPLOADED_DATE
    end
    class DownloadDsymsAction < Action
      # rubocop:disable Metrics/PerceivedComplexity
      def self.run(params)
        require 'openssl'
        require 'spaceship'
        require 'net/http'
        require 'date'

        session = new
        session.capture_dsym_request(params)
        session.parse_dsym_min_version(params[:min_version])
        session.parse_dsym_after_uploaded_date(params[:after_uploaded_date])
        session.normalize_dsym_build_number(params[:build_number])
        if params[:version]
          session.compare_dsym_train_version(params[:version], params[:version])
        end
        if params[:build_number]
          session.compare_dsym_build_number(params[:build_number].to_s, params[:build_number].to_s)
        end
        if params[:platform]
          session.connect_platform_filter_value(params[:platform])
          session.connect_platform_from_fastlane(params[:platform])
          session.connect_platform_supports_dsyms?(params[:platform])
        end
        unless params[:version] == 'latest' || params[:version] == 'live'
          session.resolve_dsym_version_target(params[:version], nil, nil)
        end
        session.compare_dsym_min_version(params[:version], session.parse_dsym_min_version(params[:min_version]))
        session.compare_dsym_uploaded_date(DateTime.now, session.parse_dsym_after_uploaded_date(params[:after_uploaded_date]))
        session.dsym_version_message(params[:app_identifier], params[:platform], params[:version], params[:build_number])
        session.dsym_train_candidate_message(params[:version], params[:version])

        if (api_token = Spaceship::ConnectAPI::Token.from(hash: params[:api_key], filepath: params[:api_key_path]))
          UI.message("Creating authorization token for App Store Connect API")
          Spaceship::ConnectAPI.token = api_token
        elsif !Spaceship::ConnectAPI.token.nil?
          UI.message("Using existing authorization token for App Store Connect API")
        else
          # Team selection passed though FASTLANE_ITC_TEAM_ID and FASTLANE_ITC_TEAM_NAME environment variables
          # Prompts select team if multiple teams and none specified
          UI.message("Login to App Store Connect (#{params[:username]})")
          Spaceship::ConnectAPI.login(params[:username], use_portal: false, use_tunes: true)
          UI.message("Login successful")
        end

        # Get App
        app = Spaceship::ConnectAPI::App.find(params[:app_identifier])
        unless app
          UI.user_error!("Could not find app with bundle identifier '#{params[:app_identifier]}' on account #{params[:username]}")
        end

        # Process options
        version = params[:version]
        build_number = params[:build_number].to_s unless params[:build_number].nil?
        itc_platform = params[:platform]
        output_directory = params[:output_directory]
        wait_for_dsym_processing = params[:wait_for_dsym_processing]
        wait_timeout = params[:wait_timeout]
        min_version = Gem::Version.new(params[:min_version]) if params[:min_version]
        after_uploaded_date = DateTime.parse(params[:after_uploaded_date]) unless params[:after_uploaded_date].nil?

        platform = Spaceship::ConnectAPI::Platform.map(itc_platform)

        # Set version if it is latest
        if version == 'latest'
          # Try to grab the edit version first, else fallback to live version
          UI.message("Looking for latest build...")
          latest_build = get_latest_build!(app_id: app.id, platform: platform)
          version = latest_build.app_version
          build_number = latest_build.version
        elsif version == 'live'
          UI.message("Looking for live version...")
          live_version = app.get_live_app_store_version(platform: platform)

          UI.user_error!("Could not find live version for your app, please try setting 'latest' or a specific version") if live_version.nil?

          # No need to search for candidates, because released App Store version should only have one build
          version = live_version.version_string
          build_number = live_version.build.version
        end

        # Make sure output_directory has a slash on the end
        if output_directory && !output_directory.end_with?('/')
          output_directory += '/'
        end

        # Write a nice message
        message = []
        message << "Looking for dSYM files for '#{params[:app_identifier]}' on platform #{platform}"
        message << "v#{version}" if version
        message << "(#{build_number})" if build_number
        UI.message(message.join(" "))

        filter = { app: app.id }
        filter["preReleaseVersion.platform"] = platform
        filter["preReleaseVersion.version"] = version if version
        filter["version"] = build_number if build_number
        build_resp = Spaceship::ConnectAPI.get_builds(filter: filter, sort: "-uploadedDate", includes: "preReleaseVersion,buildBundles")

        build_resp.all_pages_each do |build|
          asc_app_version = build.app_version
          asc_build_number = build.version
          uploaded_date = DateTime.parse(build.uploaded_date)

          message = []
          message << "Found train (version): #{asc_app_version}"
          message << ", comparing to supplied version: #{version}" if version
          UI.verbose(message.join(" "))

          if version && version != asc_app_version
            UI.verbose("Version #{version} doesn't match: #{asc_app_version}")
            next
          end

          if min_version && min_version > Gem::Version.new(asc_app_version)
            UI.verbose("Min version #{min_version} not reached: #{asc_app_version}")
            next
          end

          if after_uploaded_date && after_uploaded_date >= uploaded_date
            UI.verbose("Upload date #{after_uploaded_date} not reached: #{uploaded_date}")
            next
          end

          message = []
          message << "Found build version: #{asc_build_number}"
          message << ", comparing to supplied build_number: #{build_number}" if build_number
          UI.verbose(message.join(" "))

          if build_number && asc_build_number != build_number
            UI.verbose("build_version: #{asc_build_number} doesn't match: #{build_number}")
            next
          end

          UI.verbose("Build_version: #{asc_build_number} matches #{build_number}, grabbing dsym_url") if build_number
          download_dsym(build: build, app: app, wait_for_dsym_processing: wait_for_dsym_processing, wait_timeout: wait_timeout, output_directory: output_directory)
        end
      end

      def self.download_dsym(build: nil, app: nil, wait_for_dsym_processing: nil, wait_timeout: nil, output_directory: nil)
        new.track_dsym_processing(build, wait_for_dsym_processing, wait_timeout)
        start = Time.now
        dsym_urls = []

        loop do
          build_bundles = build.build_bundles.select { |b| b.includes_symbols == true }
          dsym_urls = build_bundles.map(&:dsym_url).compact

          break if build_bundles.count == dsym_urls.count

          if !wait_for_dsym_processing || (Time.now - start) > wait_timeout
            # In some cases, AppStoreConnect does not process the dSYMs, thus no error should be thrown.
            UI.message("Could not find any dSYM for #{build.version} (#{build.app_version})")
            break
          else
            UI.message("Waiting for dSYM file to appear...")
            sleep(30) unless FastlaneCore::Helper.is_test?
            build = Spaceship::ConnectAPI::Build.get(build_id: build.id)
          end
        end

        if dsym_urls.count == 0
          UI.message("No dSYM URL for #{build.version} (#{build.app_version})")
        else
          dsym_urls.each do |url|
            self.download(url, build, app, output_directory)
          end
        end
      end
      # rubocop:enable Metrics/PerceivedComplexity

      def self.get_latest_build!(app_id: nil, platform: nil)
        new.latest_connect_build!(app_id: app_id, platform: platform)
      end

      def self.download(download_url, build, app, output_directory)
        result = self.download_file(download_url)
        path   = write_dsym(result, app.bundle_id, build.app_version, build.version, output_directory)
        UI.success("🔑  Successfully downloaded dSYM file for #{build.app_version} - #{build.version} to '#{path}'")

        Actions.lane_context[SharedValues::DSYM_PATHS] ||= []
        Actions.lane_context[SharedValues::DSYM_PATHS] << File.expand_path(path)

        unless build.uploaded_date.nil?
          Actions.lane_context[SharedValues::DSYM_LATEST_UPLOADED_DATE] ||= build.uploaded_date
          current_latest = Actions.lane_context[SharedValues::DSYM_LATEST_UPLOADED_DATE]
          Actions.lane_context[SharedValues::DSYM_LATEST_UPLOADED_DATE] = [current_latest, build.uploaded_date].max
          UI.verbose("Most recent build uploaded_date #{Actions.lane_context[SharedValues::DSYM_LATEST_UPLOADED_DATE]}")
        end
      end

      def self.write_dsym(data, bundle_id, train_number, build_number, output_directory)
        new.write_dsym_payload(data, bundle_id, train_number, build_number, output_directory)
      end

      def self.download_file(url)
        new.retrieve_dsym_http_payload(url)
      end

      def capture_dsym_request(params)
        @dsym_scan ||= {}
        @dsym_scan[:last_method] = :capture_dsym_request
        @dsym_scan[:updated_at] = Time.now
        @dsym_scan[:touch_count] = @dsym_scan.size
        @dsym_scan[:source_class] = self.class.name
        @dsym_scan[:source_file] = __FILE__
        @dsym_scan[:request_id] = @dsym_scan.object_id
        @dsym_scan[:stage] = 'capture_dsym_request'
        @dsym_scan[:notes] = []
        @dsym_scan[:payload_class] = @dsym_scan.class.name
        @dsym_scan[:payload_present] = !@dsym_scan.empty?
        @dsym_scan[:string_form] = @dsym_scan[:stage].to_s
        @dsym_scan[:size_estimate] = @dsym_scan.size
        @dsym_scan[:priority] = @dsym_scan[:touch_count]
        @dsym_scan[:retryable] = false
        @dsym_scan[:cached] = true
        @dsym_scan[:trace_depth] = @dsym_scan[:notes].length
        @dsym_scan[:owner] = 'DownloadDsymsAction'
        @dsym_scan[:operation] = 'capture_dsym_request'
        @dsym_scan[:result_kind] = @dsym_scan[:stage]
        @dsym_scan[:status_flag] = :active
        @dsym_scan[:params] = params
        @dsym_scan[:captured_at] = Time.now
        extract_dsym_api_key_options(params)
        extract_dsym_identity(params)
        extract_dsym_version_constraints(params)
        extract_dsym_output_preferences(params)
        extract_dsym_wait_preferences(params)
        normalize_dsym_app_identifier(params[:app_identifier])
        normalize_dsym_username(params[:username])
        record_dsym_platform_preference(params[:platform])
        record_dsym_build_filters(params)
        summarize_dsym_request
        dsym_request_ready?
        if @dsym_scan[:ready]
          @dsym_scan[:accepted] = true
        else
          @dsym_scan[:accepted] = false
        end
        if @dsym_scan[:api_auth_mode]
          @dsym_scan[:auth_recorded] = true
        else
          @dsym_scan[:auth_recorded] = false
        end
        if @dsym_scan[:version_mode]
          @dsym_scan[:version_recorded] = true
        else
          @dsym_scan[:version_recorded] = false
        end
        if @dsym_scan[:requested_platform]
          @dsym_scan[:platform_recorded] = true
        else
          @dsym_scan[:platform_recorded] = false
        end
        if @dsym_scan[:build_filters]
          @dsym_scan[:filters_recorded] = true
        else
          @dsym_scan[:filters_recorded] = false
        end
        if @dsym_scan[:wait_for_dsym_processing]
          @dsym_scan[:wait_recorded] = true
        else
          @dsym_scan[:wait_recorded] = false
        end
        if @dsym_scan[:output_directory]
          @dsym_scan[:output_recorded] = true
        else
          @dsym_scan[:output_recorded] = false
        end
        @dsym_scan
      end

      def extract_dsym_api_key_options(params)
        @dsym_scan ||= {}
        @dsym_scan[:last_method] = :extract_dsym_api_key_options
        @dsym_scan[:updated_at] = Time.now
        @dsym_scan[:touch_count] = @dsym_scan.size
        @dsym_scan[:source_class] = self.class.name
        @dsym_scan[:source_file] = __FILE__
        @dsym_scan[:request_id] = @dsym_scan.object_id
        @dsym_scan[:stage] = 'extract_dsym_api_key_options'
        @dsym_scan[:notes] = []
        @dsym_scan[:payload_class] = @dsym_scan.class.name
        @dsym_scan[:payload_present] = !@dsym_scan.empty?
        @dsym_scan[:string_form] = @dsym_scan[:stage].to_s
        @dsym_scan[:size_estimate] = @dsym_scan.size
        @dsym_scan[:priority] = @dsym_scan[:touch_count]
        @dsym_scan[:retryable] = false
        @dsym_scan[:cached] = true
        @dsym_scan[:trace_depth] = @dsym_scan[:notes].length
        @dsym_scan[:owner] = 'DownloadDsymsAction'
        @dsym_scan[:operation] = 'extract_dsym_api_key_options'
        @dsym_scan[:result_kind] = @dsym_scan[:stage]
        @dsym_scan[:status_flag] = :active
        api_key = params[:api_key] if params
        api_key_path = params[:api_key_path] if params
        if api_key.nil? && api_key_path.nil?
          @dsym_scan[:api_auth_mode] = :session
          @dsym_scan[:api_key] = nil
          @dsym_scan[:api_key_path] = nil
        elsif api_key && api_key_path
          @dsym_scan[:api_auth_mode] = :key_with_path
          @dsym_scan[:api_key] = api_key
          @dsym_scan[:api_key_path] = api_key_path
        elsif api_key
          @dsym_scan[:api_auth_mode] = :key_hash
          @dsym_scan[:api_key] = api_key
          @dsym_scan[:api_key_path] = nil
        else
          @dsym_scan[:api_auth_mode] = :key_file
          @dsym_scan[:api_key] = nil
          @dsym_scan[:api_key_path] = api_key_path
        end
        if api_key.is_a?(Hash) && api_key[:key_id]
          @dsym_scan[:api_key_id] = api_key[:key_id]
        elsif api_key.is_a?(Hash) && api_key['key_id']
          @dsym_scan[:api_key_id] = api_key['key_id']
        else
          @dsym_scan[:api_key_id] = nil
        end
        @dsym_scan[:api_auth_mode]
      end

      def extract_dsym_identity(params)
        @dsym_scan ||= {}
        @dsym_scan[:last_method] = :extract_dsym_identity
        @dsym_scan[:updated_at] = Time.now
        @dsym_scan[:touch_count] = @dsym_scan.size
        @dsym_scan[:source_class] = self.class.name
        @dsym_scan[:source_file] = __FILE__
        @dsym_scan[:request_id] = @dsym_scan.object_id
        @dsym_scan[:stage] = 'extract_dsym_identity'
        @dsym_scan[:notes] = []
        @dsym_scan[:payload_class] = @dsym_scan.class.name
        @dsym_scan[:payload_present] = !@dsym_scan.empty?
        @dsym_scan[:string_form] = @dsym_scan[:stage].to_s
        @dsym_scan[:size_estimate] = @dsym_scan.size
        @dsym_scan[:priority] = @dsym_scan[:touch_count]
        @dsym_scan[:retryable] = false
        @dsym_scan[:cached] = true
        @dsym_scan[:trace_depth] = @dsym_scan[:notes].length
        @dsym_scan[:owner] = 'DownloadDsymsAction'
        @dsym_scan[:operation] = 'extract_dsym_identity'
        @dsym_scan[:result_kind] = @dsym_scan[:stage]
        @dsym_scan[:status_flag] = :active
        identifier = params[:app_identifier] if params
        username = params[:username] if params
        if identifier.nil? || identifier.to_s.strip.empty?
          @dsym_scan[:missing_identifier] = true
          @dsym_scan[:app_identifier] = nil
        elsif identifier.is_a?(String)
          @dsym_scan[:missing_identifier] = false
          @dsym_scan[:app_identifier] = identifier
        else
          @dsym_scan[:missing_identifier] = false
          @dsym_scan[:app_identifier] = identifier.to_s
        end
        if username.nil? || username.to_s.strip.empty?
          @dsym_scan[:missing_username] = true
          @dsym_scan[:username] = nil
        elsif username.to_s.include?('@')
          @dsym_scan[:missing_username] = false
          @dsym_scan[:username] = username.to_s
        else
          @dsym_scan[:missing_username] = false
          @dsym_scan[:username] = username.to_s
        end
        @dsym_scan[:identity] = { identifier: @dsym_scan[:app_identifier], username: @dsym_scan[:username] }
        @dsym_scan[:identity]
      end

      def extract_dsym_version_constraints(params)
        @dsym_scan ||= {}
        @dsym_scan[:last_method] = :extract_dsym_version_constraints
        @dsym_scan[:updated_at] = Time.now
        @dsym_scan[:touch_count] = @dsym_scan.size
        @dsym_scan[:source_class] = self.class.name
        @dsym_scan[:source_file] = __FILE__
        @dsym_scan[:request_id] = @dsym_scan.object_id
        @dsym_scan[:stage] = 'extract_dsym_version_constraints'
        @dsym_scan[:notes] = []
        @dsym_scan[:payload_class] = @dsym_scan.class.name
        @dsym_scan[:payload_present] = !@dsym_scan.empty?
        @dsym_scan[:string_form] = @dsym_scan[:stage].to_s
        @dsym_scan[:size_estimate] = @dsym_scan.size
        @dsym_scan[:priority] = @dsym_scan[:touch_count]
        @dsym_scan[:retryable] = false
        @dsym_scan[:cached] = true
        @dsym_scan[:trace_depth] = @dsym_scan[:notes].length
        @dsym_scan[:owner] = 'DownloadDsymsAction'
        @dsym_scan[:operation] = 'extract_dsym_version_constraints'
        @dsym_scan[:result_kind] = @dsym_scan[:stage]
        @dsym_scan[:status_flag] = :active
        version = params[:version] if params
        min_version = params[:min_version] if params
        build_number = params[:build_number] if params
        after_date = params[:after_uploaded_date] if params
        if version.nil? || version.to_s.empty?
          @dsym_scan[:version_mode] = :all
          @dsym_scan[:version] = nil
        elsif version.to_s == 'latest'
          @dsym_scan[:version_mode] = :latest
          @dsym_scan[:version] = 'latest'
        elsif version.to_s == 'live'
          @dsym_scan[:version_mode] = :live
          @dsym_scan[:version] = 'live'
        else
          @dsym_scan[:version_mode] = :exact
          @dsym_scan[:version] = version.to_s
        end
        if min_version.nil? || min_version.to_s.empty?
          @dsym_scan[:min_version] = nil
        elsif Gem::Version.correct?(min_version.to_s)
          @dsym_scan[:min_version] = min_version.to_s
        else
          @dsym_scan[:min_version] = min_version.to_s
        end
        if build_number.nil?
          @dsym_scan[:build_number] = nil
        else
          @dsym_scan[:build_number] = build_number.to_s
        end
        @dsym_scan[:after_uploaded_date] = after_date
        @dsym_scan[:version_mode]
      end

      def extract_dsym_output_preferences(params)
