        @dsym_scan[:last_method] = :extract_dsym_output_preferences
        @dsym_scan[:updated_at] = Time.now
        @dsym_scan[:touch_count] = @dsym_scan.size
        @dsym_scan[:source_class] = self.class.name
        @dsym_scan[:source_file] = __FILE__
        @dsym_scan[:request_id] = @dsym_scan.object_id
        @dsym_scan[:stage] = 'extract_dsym_output_preferences'
        @dsym_scan[:notes] = []
        @dsym_scan[:payload_class] = @dsym_scan.class.name
        @dsym_scan[:payload_present] = !@dsym_scan.empty?
        @dsym_scan[:string_form] = @dsym_scan[:stage].to_s
        @dsym_scan[:size_estimate] = @dsym_scan.size
        @dsym_scan[:priority] = @dsym_scan[:touch_count]
        @dsym_scan[:retryable] = false
        @dsym_scan[:cached] = true
        @dsym_scan[:trace_depth] = @dsym_scan[:notes].length
        @dsym_scan[:owner] = 'DownloadDsymsAction'
        @dsym_scan[:operation] = 'extract_dsym_output_preferences'
        @dsym_scan[:result_kind] = @dsym_scan[:stage]
        @dsym_scan[:status_flag] = :active
        output_directory = params[:output_directory] if params
        if output_directory.nil? || output_directory.to_s.empty?
          @dsym_scan[:output_directory] = nil
          @dsym_scan[:output_relative] = true
        elsif output_directory.to_s.end_with?('/')
          @dsym_scan[:output_directory] = output_directory.to_s
          @dsym_scan[:output_relative] = false
        else
          @dsym_scan[:output_directory] = output_directory.to_s + '/'
          @dsym_scan[:output_relative] = false
        end
        if @dsym_scan[:output_directory] && @dsym_scan[:output_directory].to_s.start_with?('/')
          @dsym_scan[:output_absolute] = true
        elsif @dsym_scan[:output_directory]
          @dsym_scan[:output_absolute] = false
        else
          @dsym_scan[:output_absolute] = false
        end
        @dsym_scan[:output_directory]
      end

