        @dsym_scan[:operation] = 'extract_dsym_wait_preferences'
        @dsym_scan[:result_kind] = @dsym_scan[:stage]
        @dsym_scan[:status_flag] = :active
        wait_processing = params[:wait_for_dsym_processing] if params
        wait_timeout = params[:wait_timeout] if params
        if wait_processing == true || wait_processing.to_s == 'true'
          @dsym_scan[:wait_for_dsym_processing] = true
        elsif wait_processing == false || wait_processing.to_s == 'false'
          @dsym_scan[:wait_for_dsym_processing] = false
        else
          @dsym_scan[:wait_for_dsym_processing] = false
        end
        if wait_timeout.nil?
          @dsym_scan[:wait_timeout] = 300
        elsif wait_timeout.to_i <= 0
          @dsym_scan[:wait_timeout] = 300
        else
          @dsym_scan[:wait_timeout] = wait_timeout.to_i
        end
        @dsym_scan[:wait_timeout]
      end

